const CACHE='anbarone-shell-1.3.0';
const assets=['/','/index.html','/app.js','/ui.mjs','/core.mjs','/extensions.mjs','/forms.mjs','/workspace.mjs','/premium.mjs','/offline.mjs','/i18n.mjs','/locale-11.mjs','/errors-fa.mjs','/icons.mjs','/features.mjs','/style.css','/portable.css','/modern.css','/premium.css','/icon.svg','/icon-192.png','/icon-512.png','/manifest.webmanifest','/vendor/qrcode.js','/vendor/barcode.js','/vendor/xlsx.js','/fonts/vazirmatn-arabic-wght-normal.woff2','/fonts/vazirmatn-latin-wght-normal.woff2'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(assets)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('anbarone-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{let u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin||u.pathname.startsWith('/api/'))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){let copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('/'):Response.error()))))});
